# @@ bisection: halve the bracket until it is small
def bisect(f, lo, hi, tol) {
    flo = f(lo)
    if flo * f(hi) > 0 {
        stop("ValueError: the bracket does not change sign")
    }
    steps = 0
    while hi - lo > tol {
        mid = 0.5 * (lo + hi)
        fmid = f(mid)
        if flo * fmid <= 0 {
            hi = mid
        }
        else {
            lo = mid
            flo = fmid
        }
        steps = py_int(steps + 1)
    }
    return 0.5 * (lo + hi), steps
}
# @@ a cubic with one real root
def cubic(x) {
    return py_fpow(x, 3) - 2.0 * x - 5.0
}
root, steps = bisect(cubic, 2.0, 3.0, 1e-10)
print("root", fmt(root, ".10f"), "after", fmt(steps + 0.0, "d"), "halvings, f(root) =", fmt(cubic(root), ".2e"))
# @@ the bracket shrinks by half each step
py_v1 = [0.01, 0.0001, 1e-08]
for py_i2 to 3 {
    tol = py_v1[py_i2]
    r, n = bisect(cubic, 2.0, 3.0, tol)
    print("tol ", fmt(tol, ".0e"), ": ", fmt(n + 0.0, "2d"), " steps, root ", fmt(r, ".8f"), sep="")
}
# @@ checks
if not (abs(cubic(root)) < 1e-08) {
    stop("AssertionError")
}
